   const descriptor=s.binding.account.descriptor(),address='0x'+Buffer.from(publicKeccak256(Buffer.from(point.x+point.y,'hex'))).subarray(12).toString('hex');assert.notEqual(address,'0x'+'0'.repeat(40));
